const ALWAYS_SAFE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-~';
const HEX = '0123456789ABCDEF';
const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder('utf-8', { fatal: false });

function isHexDigit(character) {
  return (
    (character >= '0' && character <= '9') ||
    (character >= 'a' && character <= 'f') ||
    (character >= 'A' && character <= 'F')
  );
}

export function percentDecode(value) {
  const bytes = [];

  for (let index = 0; index < value.length; index += 1) {
    if (
      value[index] === '%' &&
      index + 2 < value.length &&
      isHexDigit(value[index + 1]) &&
      isHexDigit(value[index + 2])
    ) {
      bytes.push(Number.parseInt(value.slice(index + 1, index + 3), 16));
      index += 2;
      continue;
    }

    bytes.push(...textEncoder.encode(value[index]));
  }

  return textDecoder.decode(Uint8Array.from(bytes));
}

export function percentDecodePlus(value) {
  return percentDecode(value.replaceAll('+', ' '));
}

export function quote(value, safe = '') {
  const safeCharacters = new Set(`${ALWAYS_SAFE}${safe}`);
  let encoded = '';

  for (const byte of textEncoder.encode(value)) {
    const character = String.fromCharCode(byte);
    if (safeCharacters.has(character)) {
      encoded += character;
    } else {
      encoded += `%${HEX[byte >> 4]}${HEX[byte & 15]}`;
    }
  }

  return encoded;
}

export function quotePlus(value) {
  let encoded = '';

  for (const character of value) {
    encoded += character === ' ' ? '+' : quote(character);
  }

  return encoded;
}

import { percentDecode, quote } from './text-encoding.mjs';

const PATH_SEGMENT_SAFE = "!$&'()*+,;=:@";

export class UrlPath {
  constructor(rawPath = '', extraSafeCharacters = '') {
    const decodedPath = percentDecode(rawPath);
    this.value = decodedPath
      .split('/')
      .map((segment) => quote(segment, `${PATH_SEGMENT_SAFE}${extraSafeCharacters}`))
      .join('/');
  }

  toString() {
    return this.value;
  }
}

import { percentDecodePlus, quotePlus } from './text-encoding.mjs';

function parseParameter(rawParameter) {
  const separatorIndex = rawParameter.indexOf('=');

  if (separatorIndex === -1) {
    return {
      key: percentDecodePlus(rawParameter),
      value: null,
    };
  }

  return {
    key: percentDecodePlus(rawParameter.slice(0, separatorIndex)),
    value: percentDecodePlus(rawParameter.slice(separatorIndex + 1)),
  };
}

export class UrlQuery {
  constructor(rawQuery = '') {
    this.parameters = rawQuery === '' ? [] : rawQuery.split('&').map(parseParameter);
  }

  add(values) {
    for (const [key, value] of Object.entries(values)) {
      this.parameters.push({ key: String(key), value: String(value) });
    }
    return this;
  }

  toString() {
    return this.parameters
      .map((parameter) => {
        const key = quotePlus(parameter.key);
        return parameter.value === null ? key : `${key}=${quotePlus(parameter.value)}`;
      })
      .join('&');
  }
}

import { UrlPath } from './path.mjs';
import { UrlQuery } from './query.mjs';

export class UrlFragment {
  constructor(rawFragment = '') {
    this.isEmpty = rawFragment === '';

    const queryIndex = rawFragment.indexOf('?');
    this.hasQuery = queryIndex !== -1;

    const rawPath = this.hasQuery ? rawFragment.slice(0, queryIndex) : rawFragment;
    const rawQuery = this.hasQuery ? rawFragment.slice(queryIndex + 1) : '';

    this.path = new UrlPath(rawPath, '?');
    this.query = new UrlQuery(rawQuery);
  }

  toString() {
    if (this.isEmpty) {
      return '';
    }

    const path = this.path.toString();
    if (!this.hasQuery) {
      return path;
    }

    const query = this.query.toString();
    if (path !== '') {
      return `${path}?${query}`;
    }

    return query === '' ? '?' : query;
  }
}

import { domainToASCII, domainToUnicode } from 'node:url';
import { percentDecode, quote } from './text-encoding.mjs';

const INVALID_HOST_CHARACTERS = /[!@#$%^&'"*()+=:;/]/;
const DEFAULT_PORTS = new Map([
  ['ftp', 21],
  ['ssh', 22],
  ['telnet', 23],
  ['gopher', 70],
  ['http', 80],
  ['ws', 80],
  ['https', 443],
  ['wss', 443],
]);

function invalidHost(host) {
  return (
    host !== '' &&
    (host.startsWith('.') ||
      host.includes('..') ||
      [...host].every((character) => character === '.') ||
      INVALID_HOST_CHARACTERS.test(host))
  );
}

function parsePort(rawPort) {
  if (rawPort === undefined) {
    return null;
  }

  if (!/^\d+$/.test(rawPort)) {
    throw new Error(`Invalid port '${rawPort}'.`);
  }

  const port = Number.parseInt(rawPort, 10);
  if (port < 1 || port > 65535) {
    throw new Error(`Invalid port '${rawPort}'.`);
  }

  return port;
}

function parseHost(rawHost) {
  if (invalidHost(rawHost)) {
    throw new Error(`Invalid host '${rawHost}'.`);
  }

  const decodedHost = rawHost.includes('xn--') ? domainToUnicode(rawHost) : rawHost;
  return decodedHost.toLowerCase();
}

function encodeCredential(rawCredential) {
  return quote(percentDecode(rawCredential));
}

export class UrlNetloc {
  constructor(rawNetloc) {
    this.present = rawNetloc !== null;
    this.username = null;
    this.password = null;
    this.host = '';
    this.port = null;

    if (!this.present) {
      return;
    }

    let hostAndPort = rawNetloc;
    const userInfoIndex = rawNetloc.indexOf('@');
    if (userInfoIndex !== -1) {
      const userInfo = rawNetloc.slice(0, userInfoIndex);
      hostAndPort = rawNetloc.slice(userInfoIndex + 1);
      const passwordIndex = userInfo.indexOf(':');

      if (passwordIndex === -1) {
        this.username = userInfo;
      } else {
        this.username = userInfo.slice(0, passwordIndex);
        this.password = userInfo.slice(passwordIndex + 1);
      }
    }

    let rawHost;
    let rawPort;
    if (hostAndPort.startsWith('[')) {
      const closingBracket = hostAndPort.indexOf(']');
      if (closingBracket === -1) {
        throw new Error('Invalid IPv6 URL');
      }

      rawHost = hostAndPort.slice(0, closingBracket + 1);
      const remainder = hostAndPort.slice(closingBracket + 1);
      if (remainder !== '') {
        if (!remainder.startsWith(':')) {
          throw new Error('Invalid IPv6 URL');
        }
        rawPort = remainder.slice(1);
      }
    } else {
      const portIndex = hostAndPort.indexOf(':');
      if (portIndex === -1) {
        rawHost = hostAndPort;
      } else {
        rawHost = hostAndPort.slice(0, portIndex);
        rawPort = hostAndPort.slice(portIndex + 1);
      }
    }

    if (rawHost.startsWith('[')) {
      this.host = rawHost.toLowerCase();
    } else {
      this.host = parseHost(rawHost);
    }
    this.port = parsePort(rawPort);
  }

  encodedHost() {
    if (this.host.startsWith('[')) {
      return this.host;
    }

    if (/[^\x00-\x7F]/.test(this.host)) {
      const asciiHost = domainToASCII(this.host);
      if (asciiHost === '') {
        throw new Error(`Invalid host '${this.host}'.`);
      }
      return asciiHost.toLowerCase();
    }

    return this.host;
  }

  toString(scheme = null) {
    if (!this.present) {
      return '';
    }

    let credentials = '';
    if (this.username !== null) {
      credentials = encodeCredential(this.username);
      if (this.password !== null) {
        credentials += `:${encodeCredential(this.password)}`;
      }
      credentials += '@';
    }

    const defaultPort = scheme === null ? undefined : DEFAULT_PORTS.get(scheme);
    const port = this.port === null || this.port === defaultPort ? '' : `:${this.port}`;
    return `${credentials}${this.encodedHost()}${port}`;
  }
}

import { UrlFragment } from './fragment.mjs';
import { UrlNetloc } from './netloc.mjs';
import { UrlPath } from './path.mjs';
import { UrlQuery } from './query.mjs';

const NETLOC_SCHEMES = new Set([
  'file',
  'ftp',
  'git',
  'git+ssh',
  'gopher',
  'http',
  'https',
  'imap',
  'nfs',
  'nntp',
  'prospero',
  'rsync',
  'rtsp',
  'rtspu',
  'sftp',
  'shttp',
  'snews',
  'ssh',
  'svn',
  'svn+ssh',
  'telnet',
  'wais',
  'ws',
  'wss',
]);

function cleanUrl(value) {
  return value.replace(/[\t\r\n]/g, '').replace(/^[\x00-\x20]+|[\x00-\x20]+$/g, '');
}

export class Furl {
  constructor(url) {
    let remainder = cleanUrl(String(url));

    const fragmentIndex = remainder.indexOf('#');
    const rawFragment = fragmentIndex === -1 ? '' : remainder.slice(fragmentIndex + 1);
    if (fragmentIndex !== -1) {
      remainder = remainder.slice(0, fragmentIndex);
    }

    const queryIndex = remainder.indexOf('?');
    const rawQuery = queryIndex === -1 ? '' : remainder.slice(queryIndex + 1);
    if (queryIndex !== -1) {
      remainder = remainder.slice(0, queryIndex);
    }

    this.scheme = null;
    const schemeMatch = /^([A-Za-z][A-Za-z0-9+.-]*):(.*)$/.exec(remainder);
    if (schemeMatch && !schemeMatch[1].includes('/')) {
      this.scheme = schemeMatch[1].toLowerCase();
      remainder = schemeMatch[2];
    }

    let rawNetloc = null;
    if (remainder.startsWith('//')) {
      const pathIndex = remainder.indexOf('/', 2);
      if (pathIndex === -1) {
        rawNetloc = remainder.slice(2);
        remainder = '';
      } else {
        rawNetloc = remainder.slice(2, pathIndex);
        remainder = remainder.slice(pathIndex);
      }
    }

    this.netloc = new UrlNetloc(rawNetloc);
    this.path = new UrlPath(remainder);
    this.query = new UrlQuery(rawQuery);
    this.fragment = new UrlFragment(rawFragment);
  }

  get host() {
    return this.netloc.present ? this.netloc.host : null;
  }

  get url() {
    let result = '';

    if (this.scheme !== null) {
      result += `${this.scheme}:`;
      if (this.netloc.present || NETLOC_SCHEMES.has(this.scheme)) {
        result += '//';
      }
    } else if (this.netloc.present) {
      result += '//';
    }

    result += this.netloc.toString(this.scheme);
    result += this.path.toString();

    const query = this.query.toString();
    if (query !== '') {
      result += `?${query}`;
    }

    const fragment = this.fragment.toString();
    if (fragment !== '') {
      result += `#${fragment}`;
    }

    return result;
  }
}

export function furl(url) {
  return new Furl(url);
}

const OPTIONS = [
  { name: 'a', flags: ['--a'], metavar: 'A' },
  { name: 'b', flags: ['--b'], metavar: 'B' },
  { name: 'c', flags: ['--c'], metavar: 'C' },
];

function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

function printErrorAndExit(programName, message) {
  console.error(usage(programName));
  console.error(`${programName}: error: ${message}`);
  process.exit(2);
}

function printHelpAndExit(programName) {
  console.log(usage(programName));
  console.log('');
  console.log('options:');
  console.log('  -h, --help  show this help message and exit');
  console.log('  --a A');
  console.log('  --b B');
  console.log('  --c C');
  process.exit(0);
}

function matchLongOption(token) {
  const optionText = token.includes('=') ? token.slice(0, token.indexOf('=')) : token;
  const matches = OPTIONS.filter((option) => option.flags[0].startsWith(optionText));
  return matches.length === 1 ? matches[0] : null;
}

function looksLikeOption(token) {
  if (token === '-' || /^-\d/.test(token)) {
    return false;
  }
  return token.startsWith('-');
}

export function parseCommandLine(argv, programName) {
  const values = {};
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help' || (token.startsWith('--') && '--help'.startsWith(token) && token.length > 2)) {
      printHelpAndExit(programName);
    }

    const option = token.startsWith('--') ? matchLongOption(token) : null;
    if (option === null) {
      unknown.push(token);
      continue;
    }

    if (token.includes('=')) {
      values[option.name] = token.slice(token.indexOf('=') + 1);
      continue;
    }

    const next = argv[index + 1];
    if (next === undefined || looksLikeOption(next)) {
      printErrorAndExit(programName, `argument ${option.flags[0]}: expected one argument`);
    }

    values[option.name] = next;
    index += 1;
  }

  if (unknown.length > 0) {
    printErrorAndExit(programName, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  const missing = OPTIONS.filter((option) => values[option.name] === undefined).map((option) => option.flags[0]);
  if (missing.length > 0) {
    printErrorAndExit(programName, `the following arguments are required: ${missing.join(', ')}`);
  }

  return values;
}

import { basename } from 'node:path';
import { parseCommandLine } from './lib/arguments.mjs';
import { furl } from './lib/furl.mjs';

const args = parseCommandLine(process.argv.slice(2), basename(process.argv[1]));

const f = furl(args.a);
console.log(f.scheme === null ? 'None' : f.scheme);
console.log(f.host === null ? 'None' : f.host);
console.log(f.path.toString());
console.log(f.query.add({ [args.b]: args.c }).toString());
console.log(f.url);

