import { spawnSync } from 'node:child_process';
const schemes = ['ftp','ssh','telnet','gopher','http','https','ws','wss','smtp','ldap','ldaps','sftp','file','custom','mailto','git','svn','nfs','rtsp'];
const ports = ['1','20','21','22','23','25','70','80','389','443','636','8080'];
const cases = [];
for (const s of schemes) cases.push(`${s}:abc`, `${s}:/abc`, `${s}://host/abc`);
for (const s of schemes) for (const p of ports) cases.push(`${s}://host:${p}/abc`);
let failures = 0;
for (const url of cases) {
  const py = spawnSync('/workspace/dataset/test6_executable', ['--a', url, '--b', 'k', '--c', 'v'], { encoding: 'utf8' });
  if (py.status !== 0) continue;
  const js = spawnSync('node', ['/output/test6.mjs', '--a', url, '--b', 'k', '--c', 'v'], { encoding: 'utf8' });
  if (js.status !== 0 || js.stdout !== py.stdout) {
    failures += 1;
    console.log(`FAIL ${url}\nPY ${JSON.stringify(py.stdout)}\nJS ${JSON.stringify(js.stdout)} ${JSON.stringify(js.stderr)}`);
  }
}
console.log(`${cases.length} cases, ${failures} mismatches`);
EOF

